# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# integration_ageing_error ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
ages <- get_ages(data_4_model)
years <- get_start_year(data_4_model):get_end_year(data_4_model)
n_ages <- length(ages)

# Each age is read correctly with probability 0.7 and 1 year too old with
# probability 0.3, and the plus group is always read correctly. The matrix is
# not symmetric, so using it transposed would give different compositions.
reads_older <- diag(0.7, n_ages)
reads_older[cbind(1:(n_ages - 1), 2:n_ages)] <- 0.3
reads_older[n_ages, n_ages] <- 1

# Rows are true ages and columns are observed ages.
ageing_error_rows <- function(matrix = reads_older, fleet = NA_character_,
                              timing = NA_real_) {
  tibble::tibble(
    type = "ageing_error",
    fleet = fleet,
    age = rep(ages, times = n_ages),
    length = NA_real_,
    timing = timing,
    observed = as.vector(t(matrix)),
    unit = "proportion",
    uncertainty = as.character(rep(ages, each = n_ages))
  )
}

# A year x age matrix of a fleet's reported quantity. Fleet 1 is fleet1, which
# has catch, and fleet 2 is survey1, which has an index.
by_year_and_age <- function(report, quantity, fleet) {
  matrix(report[[quantity]][[fleet]], ncol = n_ages, byrow = TRUE)
}

# Proportions at true age from the model's catch or index numbers at age,
# which ageing error must not change.
proportion_at_true_age <- function(report, fleet) {
  quantity <- c("catch_numbers_at_age", "index_numbers_at_age")[fleet]
  numbers <- by_year_and_age(report, quantity, fleet)
  numbers / rowSums(numbers)
}

# Each run is a full model build, so the runs are shared by the tests below.
base_run <- run_at_initial_values(data_big)
blurred_run <- run_at_initial_values(
  dplyr::bind_rows(data_big, ageing_error_rows())
)
# fleet1 has its own identity matrix, which takes precedence over the
# fleet = NA rows for every year. survey1 uses the default except in 1 year.
changed_year <- 10
mixed_run <- run_at_initial_values(dplyr::bind_rows(
  data_big,
  ageing_error_rows(),
  ageing_error_rows(diag(n_ages), timing = years[changed_year]),
  ageing_error_rows(diag(n_ages), fleet = "fleet1")
))

## IO correctness ----
test_that("ageing error moves expected age compositions to observed ages", {
  for (fleet in 1:2) {
    #' @description Test that expected proportions equal the proportions at true age times the ageing error matrix, with true age as rows.
    expect_equal(
      by_year_and_age(blurred_run[["report"]], "agecomp_proportion", fleet),
      proportion_at_true_age(blurred_run[["report"]], fleet) %*% reads_older,
      tolerance = 1e-12
    )
    #' @description Test that the expected numbers keep the observed sample size in each year.
    expect_equal(
      rowSums(
        by_year_and_age(blurred_run[["report"]], "agecomp_expected", fleet)
      ),
      rowSums(
        by_year_and_age(base_run[["report"]], "agecomp_expected", fleet)
      ),
      tolerance = 1e-12
    )
  }
  #' @description Test that ageing error changes the objective function.
  expect_false(isTRUE(all.equal(
    blurred_run[["objective"]],
    base_run[["objective"]]
  )))
})

test_that("ageing error does not change length compositions, catch, or index", {
  # Length depends on true age, and catch and index are fit to totals, so
  # only the age compositions should change.
  unchanged <- c(
    "lengthcomp_proportion", "lengthcomp_expected",
    "catch_numbers_at_age", "catch_expected",
    "index_numbers_at_age", "index_expected"
  )
  for (quantity in unchanged) {
    #' @description Test that length compositions, catch, and index are identical to the model without ageing error.
    expect_identical(
      blurred_run[["report"]][[quantity]],
      base_run[["report"]][[quantity]],
      label = quantity
    )
  }
})

test_that("each fleet and year uses its own ageing error matrix", {
  #' @description Test that a fleet's own identity matrix reproduces its expected proportions without ageing error exactly, in every year.
  expect_identical(
    mixed_run[["report"]][["agecomp_proportion"]][[1]],
    base_run[["report"]][["agecomp_proportion"]][[1]]
  )
  #' @description Test that a fleet's own identity matrix reproduces its expected numbers at age without ageing error exactly.
  expect_identical(
    mixed_run[["report"]][["agecomp_expected"]][[1]],
    base_run[["report"]][["agecomp_expected"]][[1]]
  )

  survey <- by_year_and_age(mixed_run[["report"]], "agecomp_proportion", 2)
  #' @description Test that the year with its own matrix uses that matrix and not a neighboring year's.
  expect_identical(
    survey[changed_year, ],
    by_year_and_age(
      base_run[["report"]], "agecomp_proportion", 2
    )[changed_year, ]
  )
  #' @description Test that the other years use the default matrix.
  expect_identical(
    survey[-changed_year, ],
    by_year_and_age(
      blurred_run[["report"]], "agecomp_proportion", 2
    )[-changed_year, ]
  )
})

## Edge handling ----
test_that("retrospective runs keep ageing_error rows", {
  #' @description Skip the test unless explicitly enabled for heavy integration testing.
  testthat::skip_if_not(
    testthat:::env_var_is_true("RUN_SLOW_TESTS"),
    message = "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  data_with_ageing_error <- dplyr::bind_rows(data_big, ageing_error_rows())
  parameters <- suppressMessages(
    setup_default_parameters(FIMSFrame(data_with_ageing_error))
  )
  fit <- run_modified_data_fims(
    years_to_remove = 1,
    data = data_with_ageing_error,
    parameters = parameters
  )
  report <- get_obj(fit)[["report"]]()
  clear()

  #' @description Test that the peeled model applied the ageing error matrix rather than dropping it.
  expect_equal(
    by_year_and_age(report, "agecomp_proportion", 1),
    proportion_at_true_age(report, 1) %*% reads_older,
    tolerance = 1e-12
  )
})

## Error handling ----
